public int characterReplacement(String s, int k) {
    int n = s.length();
    int best = 0;
    for (int i = 0; i < n; i++) {
        int[] count = new int[26];
        int maxFreq = 0;
        for (int j = i; j < n; j++) {
            count[s.charAt(j) - 'A']++;
            maxFreq = Math.max(maxFreq, count[s.charAt(j) - 'A']);
            int windowLen = j - i + 1;
            if (windowLen - maxFreq <= k) {
                best = Math.max(best, windowLen);
            }
        }
    }
    return best;
}

